import {
	BACKGROUND_CONTEXT,
	type Context,
} from "@earendil-works/chord/context";
import type { Api, Model } from "@earendil-works/pi-ai";
import type { Models } from "@earendil-works/pi-ai/models";
import {
	AssistantEntry,
	type Conversation,
	createRegistry,
	type EntryId,
	type Extension,
	Harness,
	MemoryStorage,
	type Storage,
	type Submission,
} from "@earendil-works/pi-durable";
import { NodeExecutionEnv } from "@earendil-works/pi-durable/env/node";
import { CodingTools } from "@earendil-works/pi-durable/tools";

import { GitStorage } from "./storage/git-storage.ts";
import { git } from "./storage/git.ts";
import { GitSync, isTurnBoundary } from "./storage/sync.ts";
import type { Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

const context: Context = BACKGROUND_CONTEXT;

const POSTED_KIND = "pi-action.posted";
const COMMENT_KIND = "pi-action.comment";
const KEY_FIELD = "key";
const URL_FIELD = "url";

export const threadRef = (issueNumber: number): string =>
	`refs/pi/threads/${issueNumber}`;

export interface ThreadOptions {
	cwd: string;
	/** The issue or PR; undefined for a one-off prompt, which is kept in memory only. */
	issueNumber?: number | undefined;
	models: Models;
	model: Model<Api>;
	log: Log;
	remote?: string | undefined;
	/** pi-durable extensions from the `extensions` input, installed after the coding tools. */
	extensions?: readonly Extension[];
	/** Variables the tools' shell gets on top of the process environment (see `toolEnv()`). */
	toolEnv?: Readonly<Record<string, string>> | undefined;
}

export interface ThreadInput {
	/** Stable per GitHub item, e.g. `comment-123`: resubmitting it returns the same submission. */
	key: string;
	content: string;
	data: Record<string, string>;
	/** Place the input as this entry instead of a comment (an answer to a question: `ui.answer`). */
	entry?: { kind: string; data: Record<string, string | boolean> } | undefined;
}

interface Persistence {
	ref: string;
	storage: GitStorage;
	sync: GitSync;
	startedAt: Date | undefined;
	isNew: boolean;
}

async function openPersistence(
	options: ThreadOptions,
	issueNumber: number,
): Promise<Persistence> {
	const { cwd, log } = options;
	const ref = threadRef(issueNumber);
	const sync = new GitSync({
		repo: cwd,
		ref,
		log: log.info,
		remote: options.remote,
	});
	const remoteTip = await sync.fetch();
	const storage = await GitStorage.open({
		repo: cwd,
		ref,
		author: {
			name: "pi-action",
			email: "pi-action@users.noreply.github.com",
		},
		onCommit: ({ tip, batches }) => {
			if (isTurnBoundary(batches)) {
				sync.schedule(tip).catch((error: unknown) => {
					log.warning(getErrorMessage(error));
				});
			}
		},
	});
	return {
		ref,
		storage,
		sync,
		isNew: remoteTip === undefined,
		startedAt: remoteTip ? await rootCommitTime(cwd, ref) : undefined,
	};
}

/**
 * One GitHub issue or PR as a durable pi conversation, stored in git on refs/pi/threads/<n> and pushed to the
 * remote at every turn boundary. Without an issue number, the conversation lives in memory for this run only.
 */
export class Thread {
	private closed = false;
	private readonly harness: Harness;
	private readonly root: Conversation;
	private readonly persistence: Persistence | undefined;

	private constructor(
		harness: Harness,
		root: Conversation,
		persistence: Persistence | undefined,
	) {
		this.harness = harness;
		this.root = root;
		this.persistence = persistence;
	}

	static async open(options: ThreadOptions): Promise<Thread> {
		const { cwd } = options;
		const persistence =
			options.issueNumber === undefined
				? undefined
				: await openPersistence(options, options.issueNumber);
		const storage: Storage = persistence?.storage ?? new MemoryStorage();
		const registry = createRegistry();
		registry.install(CodingTools);
		for (const extension of options.extensions ?? []) {
			registry.install(extension);
		}
		const harness = await Harness.open(
			storage,
			{
				models: options.models,
				registry,
				env: ({ cwd: dir }) =>
					new NodeExecutionEnv({
						cwd: dir ?? cwd,
						shellEnv: { ...options.toolEnv },
					}),
				settings: { retry: { maxRetries: 2 } },
			},
			context,
		);
		const agent = {
			model: { provider: options.model.provider, modelId: options.model.id },
			cwd,
		};
		const root = await harness.root(context, { agent });
		await root.configure(agent, context); // the model may differ from the last run's
		harness.resume(); // finish whatever a previous, interrupted run left
		return new Thread(harness, root, persistence);
	}

	/** The thread's ref, when it is stored in git. */
	get ref(): string | undefined {
		return this.persistence?.ref;
	}

	/** A thread nothing was stored for yet (always, in memory). */
	get isNew(): boolean {
		return this.persistence?.isNew ?? true;
	}

	/** When the thread's first commit was made; undefined for a new thread. */
	get startedAt(): Date | undefined {
		return this.persistence?.startedAt;
	}

	/** Comments arriving while a run works join it (steer); otherwise they start one. */
	async submit(input: ThreadInput): Promise<Submission> {
		return this.root.submit(
			{
				type: "input",
				content: input.content,
				requestId: input.key,
				whenBusy: "steer",
				entry: input.entry ?? {
					kind: COMMENT_KIND,
					data: { key: input.key, ...input.data },
				},
			},
			context,
		);
	}

	/** The text of a run's answer, and whether it called tools (a run that ended on a `terminate` round). */
	async answerText(
		answer: EntryId,
	): Promise<{ text: string; toolCalls: boolean }> {
		const entry = await this.root.commit(
			async (tx) => tx.entry(AssistantEntry, answer),
			context,
		);
		const message = entry?.model?.[0];
		if (message?.role !== "assistant") {
			return { text: "", toolCalls: false };
		}
		return {
			text: message.content
				.flatMap((block) => (block.type === "text" ? [block.text] : []))
				.join("")
				.trim(),
			toolCalls: message.content.some((block) => block.type === "toolCall"),
		};
	}

	/** Results already posted (`answer-<entryId>`, `error-<submissionId>`), with their comment URLs. */
	async postedResults(): Promise<Map<string, string>> {
		const posted = new Map<string, string>();
		let cursor: Parameters<Conversation["entries"]>[2];
		do {
			// oxlint-disable-next-line eslint/no-await-in-loop -- pages follow each other
			const page = await this.root.entries(
				{ order: "ascending" },
				500,
				cursor,
				context,
			);
			for (const { kind, data } of page.items) {
				if (kind === POSTED_KIND && typeof data === "object" && data !== null) {
					const key: unknown = Reflect.get(data, KEY_FIELD);
					const url: unknown = Reflect.get(data, URL_FIELD);
					if (typeof key === "string") {
						posted.set(key, typeof url === "string" ? url : "");
					}
				}
			}
			cursor = page.next;
		} while (cursor !== undefined);
		return posted;
	}

	async markPosted(key: string, url: string): Promise<void> {
		await this.root.submit(
			{
				type: "write",
				entry: { kind: POSTED_KIND, data: { key, url } },
				requestId: `posted-${key}`,
			},
			context,
		);
	}

	async abort(): Promise<void> {
		await this.root.abort(context);
	}

	/** Push what is committed so far; throws if the remote moved under us. */
	async push(): Promise<void> {
		await this.persistence?.sync.flush(this.persistence.storage.tip);
	}

	async close(): Promise<void> {
		if (this.closed) {
			return;
		}
		this.closed = true;
		await this.harness.close(context);
		await this.push();
	}
}

/** When the thread's root commit was made. */
async function rootCommitTime(
	cwd: string,
	ref: string,
): Promise<Date | undefined> {
	const out = await git(cwd, [
		"log",
		"--max-parents=0",
		"--format=%cI",
		ref,
	]).catch(() => "");
	const [time] = out.trim().split("\n");
	return time ? new Date(time) : undefined;
}
// The action's `if: always()` step: push the thread ref if the main step left commits unpushed (cancelled,
// timed out, or crashed). Pushes are fast-forward only, so this never overwrites another run's history.
import { info, warning } from "@actions/core";
import { context } from "@actions/github";

import { parsePositiveInteger } from "./inputs.ts";
import { git } from "./storage/git.ts";
import { GitSync } from "./storage/sync.ts";
import { threadRef } from "./thread.ts";
import type { Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

const ISSUE_KEY = "issue";
const PULL_REQUEST_KEY = "pull_request";
const PR_NUMBER_ENV = "INPUT_PR_NUMBER";

function threadNumber(payload: Record<string, unknown>): number | undefined {
	const subject: unknown = payload[ISSUE_KEY] ?? payload[PULL_REQUEST_KEY];
	const number: unknown =
		typeof subject === "object" && subject !== null
			? Reflect.get(subject, "number")
			: undefined;
	return typeof number === "number" ? number : undefined;
}

export async function pushThread(
	payload: Record<string, unknown>,
	cwd: string,
	log: Log,
	prNumber?: number,
): Promise<"pushed" | "up-to-date" | "nothing" | "failed"> {
	// The main step works on pr_number's thread when it is set, whatever the event.
	const number = prNumber ?? threadNumber(payload);
	if (number === undefined) {
		return "nothing";
	}
	const ref = threadRef(number);
	let tip: string;
	try {
		tip = (await git(cwd, ["rev-parse", "--verify", "-q", ref])).trim();
	} catch {
		log.info(`${ref}: nothing to push`);
		return "nothing";
	}
	try {
		const sync = new GitSync({ repo: cwd, ref, log: log.info });
		if ((await sync.remoteHead()) === tip) {
			log.info(`${ref} is already saved at ${tip.slice(0, 7)}`);
			return "up-to-date";
		}
		await sync.flush(tip);
		log.info(`${ref} is saved at ${tip.slice(0, 7)}`);
		return "pushed";
	} catch (error) {
		log.warning(`Could not push ${ref}: ${getErrorMessage(error)}`);
		return "failed";
	}
}

if (process.argv[1]?.endsWith("push.ts") === true) {
	pushThread(
		context.payload,
		process.cwd(),
		{ info, warning },
		parsePositiveInteger(process.env[PR_NUMBER_ENV] ?? ""),
	).catch((error: unknown) => {
		warning(getErrorMessage(error));
	});
}
// Moving a GitStorage ref between a local repository and a remote: fetch it before opening, push it as it grows.
import { setTimeout as sleep } from "node:timers/promises";

import type { Batch } from "./git-storage.ts";
import { assertRefName, git, GitError } from "./git.ts";

export class GitSyncConflictError extends Error {
	readonly ref: string;
	constructor(ref: string, detail: string) {
		super(`Push of ${ref} was rejected (another writer moved it): ${detail}`);
		this.name = "GitSyncConflictError";
		this.ref = ref;
	}
}

/** Runs git in a directory and resolves with its stdout, like `git()`; tests replace it. */
export type GitRunner = (
	dir: string,
	args: readonly string[],
) => Promise<string>;

export interface GitSyncOptions {
	/** The work tree (or git dir) to run git in. */
	readonly repo: string;
	readonly ref: string;
	/** Default "origin". */
	readonly remote?: string | undefined;
	readonly log?: (message: string) => void;
	/**
	 * How long to wait before each retry of a push that failed for another reason than a conflict (a GitHub-side
	 * `[remote rejected] ... (failed)`, a network error); its length is the number of retries. Default 1 s, 3 s, 10 s.
	 */
	readonly retryDelaysMs?: readonly number[] | undefined;
	/** Default `git()`. */
	readonly git?: GitRunner | undefined;
}

const RETRY_DELAYS_MS = [1000, 3000, 10_000] as const;
/**
 * git push's status line for a ref the remote refused because the push is not a fast-forward of what it has
 * (` ! [rejected]        <src> -> <ref> (fetch first)`, `(non-fast-forward)`, or `(stale info)` for a lease).
 * Anything else, such as ` ! [remote rejected] <src> -> <ref> (failed)`, is not a conflict and may pass.
 */
const CONFLICT_PATTERN =
	/^\s*!\s*\[rejected\]\s.*\((?:fetch first|non-fast-forward|stale info)\)\s*$/mu;
const MESSAGE_KINDS = new Set(["pi.assistant", "pi.tool-result"]);

/** A model response or tool result was stored: the end of a turn (or of one of its tool calls). */
export function isTurnBoundary(batches: readonly Batch[]): boolean {
	return batches.some((batch) =>
		batch.writes.some(
			(write) => write.type === "entry" && MESSAGE_KINDS.has(write.value.kind),
		),
	);
}

/**
 * Pushes are fast-forward only, so a concurrent writer on the same ref makes the later push fail
 * (GitSyncConflictError) instead of overwriting the other's history; that stops pushing for good. Other failures
 * are retried a few times, then reported to the callers waiting on that push, and the next schedule or flush tries
 * again. Pushes are coalesced: at most one runs, and the newest scheduled tip goes next.
 */
export class GitSync {
	readonly ref: string;
	readonly remote: string;
	private readonly repo: string;
	private readonly log: (message: string) => void;
	/** What the remote ref is known to point at. */
	private remoteTip: string | undefined;
	private wanted: string | undefined;
	private running: Promise<void> | undefined;
	/** Why pushing stopped for good: another writer moved the remote ref. */
	private failure: GitSyncConflictError | undefined;
	private readonly retryDelaysMs: readonly number[];
	private readonly git: GitRunner;

	constructor(options: GitSyncOptions) {
		assertRefName(options.ref);
		this.repo = options.repo;
		this.ref = options.ref;
		this.remote = options.remote ?? "origin";
		this.log = options.log ?? (() => undefined);
		this.retryDelaysMs = options.retryDelaysMs ?? RETRY_DELAYS_MS;
		this.git = options.git ?? git;
	}

	/**
	 * Make the local ref equal the remote one (creating, moving, or deleting it). Returns the remote tip, undefined
	 * when the remote has no such ref yet.
	 */
	async fetch(): Promise<string | undefined> {
		const tip = await this.remoteHead();
		if (tip === undefined) {
			await this.git(this.repo, ["update-ref", "-d", this.ref]).catch(
				() => undefined,
			);
			this.log(`${this.ref}: new on ${this.remote}`);
		} else {
			await this.git(this.repo, [
				"fetch",
				"--quiet",
				"--no-tags",
				"--no-write-fetch-head",
				this.remote,
				`+${this.ref}:${this.ref}`,
			]);
			this.log(`${this.ref}: fetched ${tip.slice(0, 7)}`);
		}
		return tip;
	}

	/** Look up the remote tip without touching the local ref; undefined when the remote has no such ref. */
	async remoteHead(): Promise<string | undefined> {
		const stdout = await this.git(this.repo, [
			"ls-remote",
			"--refs",
			this.remote,
			this.ref,
		]);
		const line = stdout.split("\n").find((l) => l.endsWith(`\t${this.ref}`));
		this.remoteTip = line?.split("\t")[0];
		return this.remoteTip;
	}

	/** Push `tip` soon; resolves when it (or a newer scheduled tip) is pushed. */
	async schedule(tip: string): Promise<void> {
		if (this.failure) {
			throw this.failure;
		}
		this.wanted = tip;
		this.running ??= this.drain().finally(() => {
			this.running = undefined;
		});
		return this.running;
	}

	/** Push `tip` now (after any push in flight); throws why pushing stopped, if it did. */
	async flush(tip: string | undefined): Promise<void> {
		if (this.running !== undefined) {
			await this.running.catch(() => undefined);
		}
		if (this.failure) {
			throw this.failure;
		}
		if (tip !== undefined && tip !== this.remoteTip) {
			await this.schedule(tip);
		}
	}

	private async drain(): Promise<void> {
		let failures = 0;
		while (this.wanted !== undefined && this.wanted !== this.remoteTip) {
			const tip = this.wanted;
			// oxlint-disable-next-line eslint/no-await-in-loop -- pushes go one at a time, newest tip next
			const detail = await this.push(tip);
			if (detail === undefined) {
				failures = 0;
				this.remoteTip = tip;
				this.log(`${this.ref}: pushed ${tip.slice(0, 7)}`);
			} else if (CONFLICT_PATTERN.test(detail)) {
				// The remote has history this one lacks: every later push would be refused the same way.
				this.failure = new GitSyncConflictError(this.ref, detail);
				throw this.failure;
			} else {
				const delay = this.retryDelaysMs[failures];
				failures += 1;
				if (delay === undefined) {
					throw new Error(
						`Push of ${this.ref} failed (${failures} attempts): ${detail}`,
					);
				}
				this.log(
					`${this.ref}: push of ${tip.slice(0, 7)} failed, retrying in ${delay} ms: ${detail}`,
				);
				// oxlint-disable-next-line eslint/no-await-in-loop -- a retry waits for the backoff
				await sleep(delay);
			}
		}
	}

	/** Push `tip` to the ref; resolves with why it failed (git's stderr), undefined when it was pushed. */
	private async push(tip: string): Promise<string | undefined> {
		try {
			await this.git(this.repo, [
				"push",
				"--quiet",
				"--no-verify",
				this.remote,
				`${tip}:${this.ref}`,
			]);
			return undefined;
		} catch (error) {
			return (error instanceof GitError && error.stderr) || String(error);
		}
	}
}
// The git side of GitStorage. Objects are hashed and written as loose objects in-process (a step is one blob,
// one tree, and one commit, so spawning git for each would cost more than the write). Everything else goes through
// git: the object directory and hash come from rev-parse, the ref moves with update-ref's compare-and-swap, and reads
// are one rev-list plus one long-lived `git cat-file --batch`. So any repository git can open works, SHA-256 and
// reftable included.
import {
	type ChildProcessWithoutNullStreams,
	execFile,
	spawn,
} from "node:child_process";
import { createHash } from "node:crypto";
import { promises as fs } from "node:fs";
import { dirname, join, resolve as resolvePath } from "node:path";
import { deflateSync } from "node:zlib";

interface GitObject {
	readonly type: string;
	readonly content: Buffer;
}
export interface Signature {
	readonly name: string;
	readonly email: string;
}
export interface ChainCommit {
	readonly id: string;
	readonly parents: readonly string[];
}

const OBJECT_ID = /^(?:[0-9a-f]{40}|[0-9a-f]{64})$/u;
const BAD_TREE_NAME = /[/\0]/u;
const IDENT_CRUD = /[<>\n\0]/gu;

export class RefConflictError extends Error {
	readonly ref: string;
	readonly expected: string | undefined;
	readonly actual: string | undefined;
	constructor(
		ref: string,
		expected: string | undefined,
		actual: string | undefined,
		options?: { cause?: unknown },
	) {
		super(
			`Ref ${ref} moved: expected ${expected ?? "(none)"}, found ${actual ?? "(none)"}`,
			options,
		);
		this.name = "RefConflictError";
		this.ref = ref;
		this.expected = expected;
		this.actual = actual;
	}
}

/** Control characters, space, and the characters check-ref-format forbids anywhere. */
function hasForbiddenChar(ref: string): boolean {
	for (const ch of ref) {
		const code = ch.codePointAt(0) ?? 0;
		if (code <= 0x20 || code === 0x7f || "~^:?*[\\".includes(ch)) {
			return true;
		}
	}
	return false;
}

/** Rough check-ref-format: refs/..., no "..", control chars, spaces, ~^:?*[\\, "@{", ".lock" components. */
export function assertRefName(ref: string): void {
	const bad =
		!ref.startsWith("refs/") ||
		ref.endsWith("/") ||
		ref.endsWith(".") ||
		ref.includes("..") ||
		ref.includes("//") ||
		ref.includes("@{") ||
		hasForbiddenChar(ref) ||
		ref
			.split("/")
			.some(
				(part) => part === "" || part.startsWith(".") || part.endsWith(".lock"),
			);
	if (bad) {
		throw new Error(`Invalid ref name: ${ref}`);
	}
}

export class GitError extends Error {
	readonly stderr: string;
	constructor(args: readonly string[], stderr: string) {
		super(`git ${args.join(" ")} failed: ${stderr.trim()}`);
		this.name = "GitError";
		this.stderr = stderr.trim();
	}
}

/** Run git in `dir`; resolves with stdout, rejects with a GitError on a nonzero exit. */
export async function git(
	dir: string,
	args: readonly string[],
): Promise<string> {
	return new Promise((resolve, reject) => {
		execFile(
			"git",
			["-C", dir, ...args],
			{ maxBuffer: 64 * 1024 * 1024 },
			(error, stdout, stderr) => {
				if (error) {
					reject(new GitError(args, stderr || error.message));
				} else {
					resolve(stdout);
				}
			},
		);
	});
}

/** Drop the characters git's ident format can't hold. */
function cleanIdent(text: string): string {
	return text.replaceAll(IDENT_CRUD, "");
}

function assertObjectId(id: string): void {
	if (!OBJECT_ID.test(id)) {
		throw new Error(`Bad object id ${id}`);
	}
}

export class GitRepo {
	/** The path git runs in (`git -C`): a work tree, a git dir, a bare repo, or a linked worktree. */
	readonly dir: string;
	private readonly objects: string;
	private readonly hash: "sha1" | "sha256";
	private catFile: CatFile | undefined;

	private constructor(dir: string, objects: string, hash: "sha1" | "sha256") {
		this.dir = dir;
		this.objects = objects;
		this.hash = hash;
	}

	static async open(path: string): Promise<GitRepo> {
		const out = await git(path, [
			"rev-parse",
			"--show-object-format",
			"--git-path",
			"objects",
		]).catch((error: unknown) => {
			throw new Error(`Not a git repository: ${path}`, { cause: error });
		});
		const [format = "", objects = ""] = out.trim().split("\n");
		return new GitRepo(
			path,
			resolvePath(path, objects),
			format === "sha256" ? "sha256" : "sha1",
		);
	}

	/** Write a loose object (unless it exists) and return its id. */
	private async writeObject(
		type: "blob" | "tree" | "commit",
		content: Buffer,
	): Promise<string> {
		const raw = Buffer.concat([
			Buffer.from(`${type} ${content.length}\0`),
			content,
		]);
		const id = createHash(this.hash).update(raw).digest("hex");
		const path = join(this.objects, id.slice(0, 2), id.slice(2));
		const present = await fs
			.access(path)
			.then(() => true)
			.catch(() => false);
		if (!present) {
			await fs.mkdir(dirname(path), { recursive: true });
			const tmp = `${path}.${process.pid}.${Math.random().toString(36).slice(2)}.tmp`;
			await fs.writeFile(tmp, deflateSync(raw), { mode: 0o444 });
			await fs.rename(tmp, path);
		}
		return id;
	}

	async writeBlob(content: string): Promise<string> {
		return this.writeObject("blob", Buffer.from(content));
	}

	/** A tree of regular files; names are sorted as git requires. */
	async writeTree(files: Readonly<Record<string, string>>): Promise<string> {
		const names = Object.keys(files).toSorted((a, b) =>
			Buffer.compare(Buffer.from(a), Buffer.from(b)),
		);
		const parts: Buffer[] = [];
		for (const name of names) {
			const id = files[name] ?? "";
			if (!OBJECT_ID.test(id) || BAD_TREE_NAME.test(name)) {
				throw new Error(`Bad tree entry ${name}`);
			}
			parts.push(Buffer.from(`100644 ${name}\0`), Buffer.from(id, "hex"));
		}
		return this.writeObject("tree", Buffer.concat(parts));
	}

	async writeCommit(input: {
		tree: string;
		parents: readonly string[];
		author: Signature;
		message: string;
		time?: Date;
	}): Promise<string> {
		const seconds = Math.floor((input.time ?? new Date()).getTime() / 1000);
		const who = `${cleanIdent(input.author.name)} <${cleanIdent(input.author.email)}> ${seconds} +0000`;
		const lines = [
			`tree ${input.tree}`,
			...input.parents.map((p) => `parent ${p}`),
			`author ${who}`,
			`committer ${who}`,
		];
		return this.writeObject(
			"commit",
			Buffer.from(`${lines.join("\n")}\n\n${input.message}`),
		);
	}

	/** Every commit reachable from `tip`, oldest first, with its parents. */
	async commits(tip: string): Promise<ChainCommit[]> {
		assertObjectId(tip);
		const out = await git(this.dir, [
			"rev-list",
			"--reverse",
			"--parents",
			tip,
		]);
		return out
			.split("\n")
			.filter(Boolean)
			.map((line) => {
				const [id = "", ...parents] = line.split(" ");
				return { id, parents };
			});
	}

	/** A file in a commit's tree (`<commit>:<path>`); rejects when it is missing. */
	async readFile(commit: string, path: string): Promise<Buffer> {
		assertObjectId(commit);
		this.catFile ??= new CatFile(this.dir);
		const object = await this.catFile.read(`${commit}:${path}`);
		if (object.type !== "blob") {
			throw new Error(`${commit}:${path} is a ${object.type}, not a file`);
		}
		return object.content;
	}

	/** The commit `ref` points at; undefined when it doesn't exist. */
	async readRef(ref: string): Promise<string | undefined> {
		assertRefName(ref);
		const symbolic = await git(this.dir, ["symbolic-ref", "-q", ref])
			.then(() => true)
			.catch(() => false);
		if (symbolic) {
			throw new Error(`Ref ${ref} is not a direct ref`);
		}
		const id = await git(this.dir, ["rev-parse", "-q", "--verify", ref]).catch(
			() => undefined,
		);
		return id?.trim() || undefined;
	}

	/**
	 * Compare-and-swap `ref` from `expected` (undefined: must not exist) to `value`. git update-ref takes the ref's
	 * lock, so a concurrent fetch, update-ref, or another GitStorage sees one winner; losing throws RefConflictError.
	 */
	async updateRef(
		ref: string,
		value: string,
		expected: string | undefined,
	): Promise<void> {
		assertRefName(ref);
		assertObjectId(value);
		try {
			// An empty old value means "must not exist yet".
			await git(this.dir, ["update-ref", ref, value, expected ?? ""]);
		} catch (error) {
			if (!(error instanceof GitError)) {
				throw error;
			}
			const actual = await this.readRef(ref).catch(() => undefined);
			throw new RefConflictError(
				ref,
				expected,
				actual === expected ? "(locked)" : actual,
				{ cause: error },
			);
		}
	}

	async close(): Promise<void> {
		await this.catFile?.close();
		this.catFile = undefined;
	}
}

interface Waiting {
	sha: string;
	resolve: (o: GitObject) => void;
	reject: (e: Error) => void;
}

/** One `git cat-file --batch` process answering reads in order. */
class CatFile {
	private readonly child: ChildProcessWithoutNullStreams;
	private buffer = Buffer.alloc(0);
	private readonly waiting: Waiting[] = [];
	private failure: Error | undefined;

	constructor(dir: string) {
		this.child = spawn("git", ["-C", dir, "cat-file", "--batch"], {
			stdio: ["pipe", "pipe", "pipe"],
		});
		this.child.stdout.on("data", (chunk: Buffer) => {
			this.buffer = Buffer.concat([this.buffer, chunk]);
			this.drain();
		});
		const fail = (error: Error) => {
			this.failure ??= error;
			for (const w of this.waiting.splice(0)) {
				w.reject(this.failure);
			}
		};
		this.child.on("error", fail);
		this.child.on("exit", (code) => {
			fail(new Error(`git cat-file exited with ${code}`));
		});
		this.child.stdin.on("error", fail);
	}

	async read(sha: string): Promise<GitObject> {
		if (this.failure) {
			throw this.failure;
		}
		return new Promise((resolve, reject) => {
			this.waiting.push({ sha, resolve, reject });
			this.child.stdin.write(`${sha}\n`);
		});
	}

	private drain(): void {
		while (this.waiting.length > 0) {
			const eol = this.buffer.indexOf(10);
			if (eol === -1) {
				return;
			}
			const header = this.buffer.subarray(0, eol).toString();
			const [current] = this.waiting;
			if (!current) {
				return;
			}
			if (header.endsWith(" missing")) {
				this.buffer = this.buffer.subarray(eol + 1);
				this.waiting.shift();
				current.reject(new Error(`${current.sha} is missing`));
			} else if (!this.take(header, eol, current)) {
				return;
			}
		}
	}

	/** Hand the object whose header was read to `current`; false while its content hasn't fully arrived. */
	private take(header: string, eol: number, current: Waiting): boolean {
		const [, type, size] = header.split(" ");
		const end = eol + 1 + Number(size);
		if (this.buffer.length < end + 1) {
			return false;
		}
		const content = Buffer.from(this.buffer.subarray(eol + 1, end));
		this.buffer = this.buffer.subarray(end + 1);
		this.waiting.shift();
		current.resolve({ type: type ?? "", content });
		return true;
	}

	async close(): Promise<void> {
		if (this.child.exitCode !== null) {
			return;
		}
		const exited = new Promise<void>((resolve) => {
			this.child.once("exit", () => {
				resolve();
			});
		});
		this.child.stdin.end();
		await exited;
	}
}
